class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        N = len(nums)
        max_strength = -float('inf')

        # Iterate through all possible non-empty subsets using bitmasking.
        # There are 2^N total subsets. We iterate from 1 to 2^N - 1 to skip the empty set (mask 0).
        for i in range(1, 1 << N):
            current_strength = 1

            # Check which elements are included in the current subset defined by the bitmask i.
            for j in range(N):
                # If the j-th bit of i is set, include nums[j] in the product.
                if (i >> j) & 1:
                    current_strength *= nums[j]

            # Update the maximum strength found so far.
            if current_strength > max_strength:
                max_strength = current_strength

        return max_strength

