class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:

        def get_first_digit(n: int) -> int:
            # Convert number to string to easily get the first digit
            return int(str(n)[0])

        def get_last_digit(n: int) -> int:
            # Get the last digit using modulo 10
            return n % 10

        def gcd(a: int, b: int) -> int:
            # Standard Euclidean algorithm for GCD
            while b:
                a, b = b, a % b
            return a

        N = len(nums)
        beautiful_pairs_count = 0

        # Iterate through all possible pairs (i, j) such that i < j
        for i in range(N):
            for j in range(i + 1, N):

                # 1. Get the first digit of nums[i]
                first_digit_i = get_first_digit(nums[i])

                # 2. Get the last digit of nums[j]
                last_digit_j = get_last_digit(nums[j])

                # 3. Check for coprimality
                if gcd(first_digit_i, last_digit_j) == 1:
                    beautiful_pairs_count += 1

        return beautiful_pairs_count

