class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)

        # Helper function to check if a substring is balanced
        def is_balanced(sub: str) -> bool:
            if not sub:
                return True
            counts = {}
            for char in sub:
                counts[char] = counts.get(char, 0) + 1

            # Check if all characters appear the same number of times
            if not counts:
                return True

            first_count = -1
            for count in counts.values():
                if first_count == -1:
                    first_count = count
                elif count != first_count:
                    return False
            return True

        # DP array initialization
        # dp[i] stores the minimum number of balanced substrings for s[0:i] (prefix of length i)
        # Initialize with a value larger than any possible answer (n + 1 is safe)
        dp = [n + 1] * (n + 1)
        dp[0] = 0

        # Dynamic Programming iteration
        for i in range(1, n + 1):
            # Try all possible split points j (0 <= j < i)
            for j in range(i):
                # Substring is s[j:i]
                substring = s[j:i]

                if is_balanced(substring):
                    # If s[j:i] is balanced, we can potentially update dp[i]
                    # dp[j] + 1 is the number of partitions for s[0:j] plus the new partition s[j:i]
                    if dp[j] != n + 1:
                        dp[i] = min(dp[i], dp[j] + 1)

        # The result is dp[n]. If dp[n] is still n + 1, it means no partition exists, 
        # but since a single character is always balanced, a partition always exists.
        return dp[n]

