    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0

        # Iterate over all possible starting indices i
        for i in range(n):
            # Iterate over all possible ending indices j (inclusive)
            for j in range(i, n):
                # Extract the substring s[i:j+1]
                substring = s[i:j+1]

                # Count the number of '0's and '1's in the substring
                zeros = 0
                ones = 0
                for char in substring:
                    if char == '0':
                        zeros += 1
                    else:
                        ones += 1

                # Check the k-constraint
                # Condition 1: The number of 0's is at most k
                # Condition 2: The number of 1's is at most k
                if zeros <= k or ones <= k:
                    count += 1

